using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace Monja {
 public sealed class TracePane:UserControl {
  readonly dynamic app;readonly CheckedListBox books=new CheckedListBox{CheckOnClick=true,Height=90,Dock=DockStyle.Top};readonly DataGridView grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,VirtualMode=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.None};
  readonly ComboBox mode=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=240},direction=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=240};
  readonly CheckBox formula=new CheckBox{Checked=true,AutoSize=true},vba=new CheckBox{Checked=true,AutoSize=true},chart=new CheckBox{Checked=true,AutoSize=true},pivot=new CheckBox{Checked=true,AutoSize=true},indirect=new CheckBox{AutoSize=true};readonly ComboBox vbaMode=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=200};readonly TextBox filter=new TextBox{Width=230};readonly Label status=new Label{AutoSize=true};readonly TextBox notices=new TextBox{Multiline=true,ReadOnly=true,Dock=DockStyle.Bottom,Height=85,ScrollBars=ScrollBars.Vertical};
  public string LastErrorDetails{get{return lastErrorDetails;}}public bool CacheValid{get{return valid;}}public bool IsAnalyzing{get{return cancellation!=null;}}public int ResultCount{get{return rows.Count;}}public string ResultCsv{get{return Graph.Csv(rows);}}public string StatusText{get{return status.Text;}}
  public void SetLanguage(bool value){language.SelectedIndex=value?1:0;}public void ConfigureImpact(bool dependents,bool expand){direction.SelectedIndex=dependents?0:1;indirect.Checked=expand;SetMode(true);}public void NavigateResult(int row,bool target){if(row<0||row>=rows.Count)throw new ArgumentOutOfRangeException("row");grid.CurrentCell=grid.Rows[row].Cells[0];NavigateTo(target);}
  readonly Button scan=new Button{AutoSize=true},cancel=new Button{AutoSize=true,Enabled=false},export=new Button{AutoSize=true},refresh=new Button{AutoSize=true},help=new Button{AutoSize=true};readonly ComboBox language=new ComboBox{Width=90,DropDownStyle=ComboBoxStyle.DropDownList};CancellationTokenSource cancellation;List<Edge> cache=new List<Edge>(),rows=new List<Edge>();bool english,valid,hasSnapshot,localizing;string lastErrorDetails="",scanSummary="";int scanWarnings;readonly Label emptyState=new Label{AutoSize=false,TextAlign=System.Drawing.ContentAlignment.MiddleCenter,ForeColor=System.Drawing.SystemColors.GrayText,BackColor=System.Drawing.SystemColors.Window};long cacheVersion;readonly Stopwatch clock=new Stopwatch();
  public event EventHandler LanguageChanged;public bool IsEnglish{get{return english;}}
  string T(string ja,string en){return english?en:ja;}
  public TracePane(object application){app=application;BuildLayout();language.Items.AddRange(new object[]{"日本語","English"});language.SelectedIndex=PropertiesLanguage();language.SelectedIndexChanged+=(s,e)=>{english=language.SelectedIndex==1;Microsoft.Win32.Registry.SetValue(@"HKEY_CURRENT_USER\Software\Monja\ReferenceTracer","Language",english?"en":"ja");Localize();if(LanguageChanged!=null)LanguageChanged(this,EventArgs.Empty);};english=language.SelectedIndex==1;Localize();
   scan.Click+=async(s,e)=>await Analyze();cancel.Click+=(s,e)=>{if(cancellation!=null)cancellation.Cancel();};export.Click+=(s,e)=>Export();refresh.Click+=async(s,e)=>{if(ChooseBooks())await Analyze();};help.Click+=(s,e)=>MessageBox.Show(T("検索対象を選び再解析してください。ブック編集後は再解析が必要です。VBA拡張モードは信頼設定で許可された場合のみ読み取ります。標準モードは保存済み.xlsm/.xlam/.xlsbを静的解析します。未保存のコード変更は含みません。設定は自動変更しません。参照元・参照先を右クリックして移動またはコピーできます。","Choose workbooks and reanalyze. Reanalyze after edits. Extended VBA mode requires trusted access. Standard mode reads saved .xlsm/.xlam/.xlsb files and excludes unsaved code edits. No trust settings are changed. Right-click a row to navigate or copy."));
   foreach(var control in new Control[]{mode,direction,formula,vba,vbaMode,chart,pivot,indirect,filter}){if(control is ComboBox)((ComboBox)control).SelectedIndexChanged+=(s,e)=>Apply();else if(control is CheckBox)((CheckBox)control).CheckedChanged+=(s,e)=>Apply();else control.TextChanged+=(s,e)=>Apply();}
   foreach(string header in new[]{"Kind","Source","Consumer","Certainty","Direct/Indirect","Content"})grid.Columns.Add(header,header);grid.Columns[0].Width=90;grid.Columns[1].Width=230;grid.Columns[2].Width=230;grid.Columns[3].Width=100;grid.Columns[4].Width=100;grid.Columns[5].Width=350;
   grid.CellValueNeeded+=(s,e)=>{if(e.RowIndex>=rows.Count)return;var edge=rows[e.RowIndex];e.Value=new object[]{edge.Kind,edge.Source,edge.Target,edge.Certainty,edge.Indirect?"indirect":"direct",edge.Content}[e.ColumnIndex];};
   grid.ColumnHeaderMouseClick+=(s,e)=>{rows=rows.OrderBy(r=>Convert.ToString(new object[]{r.Kind,r.Source,r.Target,r.Certainty,r.Indirect,r.Content}[e.ColumnIndex])).ToList();grid.Invalidate();};
   var menu=new ContextMenuStrip();menu.Items.Add("← "+T("参照元へ移動","Go to source"),null,(s,e)=>NavigateTo(false));menu.Items.Add("→ "+T("参照先へ移動","Go to consumer"),null,(s,e)=>NavigateTo(true));menu.Items.Add(T("場所をコピー","Copy locations"),null,(s,e)=>{var edge=Current();if(edge!=null)Clipboard.SetText(edge.Source+" → "+edge.Target);});grid.ContextMenuStrip=menu;grid.CellMouseDown+=(s,e)=>{if(e.RowIndex>=0&&e.Button==MouseButtons.Right)grid.CurrentCell=grid.Rows[e.RowIndex].Cells[0];};Localize();books.ItemCheck+=(s,e)=>InvalidateCache();vbaMode.SelectedIndexChanged+=(s,e)=>{if(!localizing)InvalidateCache();};RefreshBooks();
  }
  readonly Button warnings=new Button{AutoSize=true,Visible=true};
  void BuildLayout(){
   Dock=DockStyle.Fill;MinimumSize=new System.Drawing.Size(320,180);
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3,Padding=new Padding(3)};
   layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));
   layout.RowStyles.Add(new RowStyle(SizeType.AutoSize));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.AutoSize));
   var controls=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,WrapContents=true,Margin=Padding.Empty};
   controls.Controls.AddRange(new Control[]{language,mode,direction,formula,vba,vbaMode,chart,pivot,indirect,filter,scan,cancel,export,refresh,help});
   var footer=new TableLayoutPanel{Dock=DockStyle.Fill,AutoSize=true,ColumnCount=2,RowCount=1,Margin=Padding.Empty};footer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));footer.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
   status.Dock=DockStyle.Fill;status.AutoSize=false;status.Height=36;status.Margin=new Padding(2);warnings.Click+=(s,e)=>ShowNotices();footer.Controls.Add(status,0,0);footer.Controls.Add(warnings,1,0);
   grid.MinimumSize=new System.Drawing.Size(0,70);grid.ColumnHeadersVisible=true;grid.BackgroundColor=System.Drawing.SystemColors.Window;grid.Margin=new Padding(0,3,0,3);
   layout.Controls.Add(controls,0,0);layout.Controls.Add(grid,0,1);layout.Controls.Add(footer,0,2);Controls.Add(layout);
   grid.Controls.Add(emptyState);grid.SizeChanged+=(s,e)=>UpdateEmptyState();UpdateEmptyState();
  }
  void UpdateEmptyState(){emptyState.Bounds=new System.Drawing.Rectangle(8,grid.ColumnHeadersHeight+8,Math.Max(0,grid.ClientSize.Width-16),Math.Max(0,grid.ClientSize.Height-grid.ColumnHeadersHeight-24));emptyState.Visible=rows.Count==0;emptyState.Text=!String.IsNullOrEmpty(lastErrorDetails)?T("解析を完了できませんでした。右下の「診断」でエラーの発生箇所を確認できます。","Analysis did not complete. Open Diagnostics for the failed operation."):IsAnalyzing?T("解析しています…","Analyzing…"):!hasSnapshot?T("解析結果はまだありません。「再解析」を押してください。","No analysis yet. Choose Reanalyze."):!String.IsNullOrEmpty(notices.Text)?T("一致する参照がありません。取得できなかった情報を「診断」で確認してください。","No matching references. Review unavailable information in Diagnostics."):T("一致する参照がありません。方向・種類・キーワードを確認してください。","No matching references. Check direction, types and keyword.");if(emptyState.Visible)emptyState.BringToFront();}
  void ShowNotices(){using(var dialog=new Form{Text=T("解析の注意事項","Analysis notices"),Width=650,Height=400,StartPosition=FormStartPosition.CenterParent}){dialog.Controls.Add(new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Text="Monja Excel Reference Tracer 1.0.2"+Environment.NewLine+scanSummary+Environment.NewLine+lastErrorDetails+Environment.NewLine+notices.Text});dialog.ShowDialog(this);}}
  public bool ChooseBooks(){RefreshBooks();using(var dialog=new Form{Text=T("検索対象ブック","Target workbooks"),Width=650,Height=350,StartPosition=FormStartPosition.CenterParent})using(var list=new CheckedListBox{Dock=DockStyle.Fill,CheckOnClick=true,HorizontalScrollbar=true}){for(int i=0;i<books.Items.Count;i++)list.Items.Add(books.Items[i],books.GetItemChecked(i));var ok=new Button{Text="OK",Dock=DockStyle.Bottom,Height=32,DialogResult=DialogResult.OK};dialog.Controls.Add(list);dialog.Controls.Add(ok);dialog.AcceptButton=ok;if(dialog.ShowDialog(this)!=DialogResult.OK)return false;for(int i=0;i<books.Items.Count;i++)books.SetItemChecked(i,list.GetItemChecked(i));return true;}}
  protected override void Dispose(bool disposing){if(disposing){if(cancellation!=null)cancellation.Cancel();books.Dispose();notices.Dispose();}base.Dispose(disposing);}
  int PropertiesLanguage(){return Convert.ToString(Microsoft.Win32.Registry.GetValue(@"HKEY_CURRENT_USER\Software\Monja\ReferenceTracer","Language","ja"))=="en"?1:0;}
  void Localize(){localizing=true;int oldModeSelection=mode.SelectedIndex,oldDirection=direction.SelectedIndex;mode.Items.Clear();mode.Items.AddRange(new object[]{T("全体の依存関係一覧","All dependencies"),T("選択セルの影響調査","Selected cell impact")});mode.SelectedIndex=oldModeSelection<0?0:oldModeSelection;direction.Items.Clear();direction.Items.AddRange(new object[]{T("このセルを参照している場所","Places using this cell"),T("このセルが参照している場所","Places used by this cell")});direction.SelectedIndex=oldDirection<0?0:oldDirection;formula.Text=T("数式","Formulas");vba.Text="VBA";int oldMode=vbaMode.SelectedIndex;vbaMode.Items.Clear();vbaMode.Items.AddRange(new object[]{T("VBA：保存済みファイル","VBA: saved file"),T("VBA：開いているコード（拡張）","VBA: open code (extended)")});vbaMode.SelectedIndex=oldMode<0?0:oldMode;chart.Text=T("グラフ","Charts");pivot.Text=T("ピボット","Pivots");indirect.Text=T("間接参照","Indirect");scan.Text=T("再解析","Reanalyze");cancel.Text=T("中止","Cancel");export.Text=T("CSV出力","Export CSV");refresh.Text=T("検索対象ブック","Target workbooks");warnings.Text=T("診断 v1.0.2","Diagnostics v1.0.2");help.Text=T("ヘルプ","Help");if(grid.ContextMenuStrip!=null){grid.ContextMenuStrip.Items[0].Text="← "+T("参照元へ移動","Go to source");grid.ContextMenuStrip.Items[1].Text="→ "+T("参照先へ移動","Go to consumer");grid.ContextMenuStrip.Items[2].Text=T("場所をコピー","Copy locations");}if(grid.Columns.Count==6){var headers=english?new[]{"Type","Source","Consumer","Certainty","Direct/Indirect","Reference"}:new[]{"種類","参照元","参照先","確実性","直接／間接","参照内容"};for(int i=0;i<6;i++)grid.Columns[i].HeaderText=headers[i];}localizing=false;Apply();}
  public void InvalidateCache(){cacheVersion++;valid=false;status.Text=hasSnapshot?T("変更を検出しました。再解析してください。","Changes detected. Reanalyze."):T("検索対象を選び「再解析」を押してください。","Choose target workbooks and Reanalyze.");}
  public void RefreshSelection(){if(mode.SelectedIndex==1)Apply();}
  public void SetMode(bool impact){mode.SelectedIndex=impact?1:0;Apply();}
  public void RefreshBooks(){var previous=books.Items.Cast<string>().ToDictionary(x=>x,x=>books.CheckedItems.Contains(x));books.Items.Clear();dynamic workbooks=null;try{workbooks=app.Workbooks;for(int i=1;i<=workbooks.Count;i++){dynamic b=null;try{b=workbooks.Item[i];string id=ExcelScanner.Identity(b);books.Items.Add(id,!previous.ContainsKey(id)||previous[id]);}finally{ExcelScanner.Release((object)b);}}}finally{ExcelScanner.Release((object)workbooks);}InvalidateCache();}
  public Task Analyze(){if(InvokeRequired)return (Task)Invoke(new Func<Task>(Analyze));var previous=SynchronizationContext.Current;try{if(!(previous is WindowsFormsSynchronizationContext))SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());return AnalyzeCore();}finally{SynchronizationContext.SetSynchronizationContext(previous);}}
  async Task AnalyzeCore(){if(cancellation!=null)return;var targets=new HashSet<string>(books.CheckedItems.Cast<string>());if(targets.Count==0){status.Text=T("検索対象ブックを1つ以上選択してください。","Choose at least one target workbook.");return;}lastErrorDetails="";cancellation=new CancellationTokenSource();scan.Enabled=false;cancel.Enabled=true;UpdateEmptyState();grid.Invalidate();clock.Restart();long version=cacheVersion;try{var progress=new Progress<string>(s=>status.Text=s+" / "+clock.Elapsed.TotalSeconds.ToString("F1")+"s"+(scanWarnings==0?"":" / "+T("注意事項 ","Notices ")+scanWarnings));var result=await new ExcelScanner((object)app).Scan(targets,vbaMode.SelectedIndex==1,cancellation.Token,progress,vba.Checked);cache=result.Edges;hasSnapshot=true;valid=version==cacheVersion;notices.Text=String.Join(Environment.NewLine,result.Diagnostics);scanWarnings=result.Diagnostics.Count;scanSummary="Workbooks="+result.WorkbooksScanned+" Sheets="+result.WorksheetsScanned+" FormulaCells="+result.FormulaCellsScanned+" References="+result.Edges.Count;warnings.Visible=true;Apply();if(String.IsNullOrEmpty(lastErrorDetails))status.Text=T("表示 ","Shown ")+rows.Count+T("件 / 解析 "," / analyzed ")+cache.Count+" / "+clock.Elapsed.TotalSeconds.ToString("F1")+"s"+(scanWarnings==0?"":" / "+T("注意事項 ","Notices ")+scanWarnings)+(valid?"":" / "+T("解析中に変更がありました。再解析してください。","Changes occurred during the scan. Reanalyze."));}catch(OperationCanceledException){status.Text=T("中止しました。前回の結果を保持しています。","Cancelled. Previous results retained.");}catch(Exception ex){lastErrorDetails=ex.GetType().FullName+" (0x"+ex.HResult.ToString("X8")+"): "+ex.Message+Environment.NewLine+ex.StackTrace;status.Text=T("解析エラー：","Analysis error: ")+ex.Message;}finally{cancellation.Dispose();cancellation=null;scan.Enabled=true;cancel.Enabled=false;clock.Stop();UpdateEmptyState();grid.Invalidate();}}
  void Apply(){if(localizing||grid.Columns.Count==0)return;try{IEnumerable<Edge> result=cache;if(mode.SelectedIndex==1){dynamic cell=null,sheet=null,book=null;try{cell=app.Selection;sheet=cell.Worksheet;book=sheet.Parent;var selected=new Location{Book=ExcelScanner.Identity(book),Sheet=sheet.Name,Address=cell.Address[false,false,1],Kind="range"};result=Graph.Query(cache,selected,direction.SelectedIndex==0,indirect.Checked);}finally{ExcelScanner.Release((object)book);ExcelScanner.Release((object)sheet);ExcelScanner.Release((object)cell);}}
   string key=filter.Text;rows=result.Where(e=>(e.Kind=="formula"?formula.Checked:e.Kind=="chart"?chart.Checked:e.Kind=="pivot"?pivot.Checked:vba.Checked)&&(String.IsNullOrEmpty(key)||(e.Source+" "+e.Target+" "+e.Content).IndexOf(key,StringComparison.OrdinalIgnoreCase)>=0)).ToList();grid.RowCount=rows.Count;UpdateEmptyState();grid.Invalidate();if(!String.IsNullOrEmpty(lastErrorDetails))status.Text=T("解析は完了していません。「診断」を確認してください。","Analysis did not complete. Review Diagnostics.");else if(!valid)status.Text=hasSnapshot?T("再解析が必要です。","Reanalysis required."):T("検索対象を選び「再解析」を押してください。","Choose target workbooks and Reanalyze.");else if(!IsAnalyzing&&String.IsNullOrEmpty(lastErrorDetails))status.Text=T("表示 ","Shown ")+rows.Count+T("件 / 解析 "," / analyzed ")+cache.Count+" / "+clock.Elapsed.TotalSeconds.ToString("F1")+"s"+(scanWarnings==0?"":" / "+T("注意事項 ","Notices ")+scanWarnings);}catch(Exception ex){lastErrorDetails=ex.GetType().FullName+" (0x"+ex.HResult.ToString("X8")+"): "+ex.Message+Environment.NewLine+ex.StackTrace;rows=new List<Edge>();grid.RowCount=0;UpdateEmptyState();status.Text=T("検索エラー：","Query error: ")+ex.Message;}}
  Edge Current(){return grid.CurrentCell!=null&&grid.CurrentCell.RowIndex<rows.Count?rows[grid.CurrentCell.RowIndex]:null;}
  void NavigateTo(bool target){var edge=Current();if(edge==null)return;var loc=target?edge.Target:edge.Source;dynamic workbooks=null,book=null,sheet=null;try{workbooks=app.Workbooks;for(int i=1;i<=workbooks.Count;i++){dynamic candidate=workbooks.Item[i];if(ExcelScanner.Identity(candidate)==loc.Book){book=candidate;break;}ExcelScanner.Release((object)candidate);}if(book==null)throw new InvalidOperationException(T("ブックが開いていません。場所をコピーできます。","Workbook is not open. Copy its location."));book.Activate();if(loc.Kind=="vba"){dynamic project=null,components=null,component=null,module=null,pane=null,vbe=null;try{project=book.VBProject;components=project.VBComponents;component=components.Item(loc.Module);module=component.CodeModule;pane=module.CodePane;pane.Show();pane.SetSelection(loc.Line,1,loc.Line,1);vbe=app.VBE;vbe.MainWindow.Visible=true;}finally{ExcelScanner.Release((object)vbe);ExcelScanner.Release((object)pane);ExcelScanner.Release((object)module);ExcelScanner.Release((object)component);ExcelScanner.Release((object)components);ExcelScanner.Release((object)project);}return;}if(loc.Kind=="chart"&&String.IsNullOrEmpty(loc.Address)){dynamic charts=null,chart=null;try{charts=book.Charts;chart=charts.Item(loc.Name);chart.Activate();return;}catch(System.Runtime.InteropServices.COMException){}finally{ExcelScanner.Release((object)chart);ExcelScanner.Release((object)charts);}}dynamic sheets=null;try{sheets=book.Worksheets;sheet=sheets.Item(loc.Sheet);}finally{ExcelScanner.Release((object)sheets);}sheet.Activate();if(loc.Kind=="chart"){dynamic charts=null,chart=null;try{charts=sheet.ChartObjects();chart=charts.Item(loc.Name);chart.Activate();return;}catch(System.Runtime.InteropServices.COMException){}finally{ExcelScanner.Release((object)chart);ExcelScanner.Release((object)charts);}}else if(!String.IsNullOrEmpty(loc.Address)){dynamic range=null;try{range=sheet.Range[loc.Address];range.Select();}finally{ExcelScanner.Release((object)range);}}else throw new InvalidOperationException(T("セル位置を特定できません。","Cell location is unavailable."));}catch(Exception ex){MessageBox.Show(ex.Message);}finally{ExcelScanner.Release((object)sheet);ExcelScanner.Release((object)book);ExcelScanner.Release((object)workbooks);}}
  public void Export(){using(var d=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName="monja-references.csv"})if(d.ShowDialog()==DialogResult.OK)File.WriteAllText(d.FileName,Graph.Csv(rows),new UTF8Encoding(true));}
 }
